(function () {
'use strict';
var DN = window.DN = window.DN || {};
DN.injectMedDiagrams = function () {
var slug = DN.currentSlug && DN.currentSlug();
if (!slug) return;
if (!DN.MED_DIAGRAM_MAP || !DN.medDiagrams) {
if (!DN._diagramBundleLoading) {
DN._diagramBundleLoading = new Promise(function (resolve, reject) {
var s = document.createElement('script');
s.src = '/blog/blog-diagrams.min.js?v=202605210000';
s.defer = true;
s.onload = resolve;
s.onerror = reject;
document.head.appendChild(s);
});
}
DN._diagramBundleLoading.then(function () {
DN.injectMedDiagrams();
}).catch(function () {});
return;
}
var spec = DN.MED_DIAGRAM_MAP[slug];
if (!spec || !spec.length) return;
var article = document.querySelector('article.max-w-3xl');
if (!article) return;
if (!document.getElementById('dn-med-fig-css')) {
var st = document.createElement('style');
st.id = 'dn-med-fig-css';
st.textContent =
'.dn-med-fig{margin:28px 0;background:#fff;border:1px solid var(--border,#dcd5c8);border-radius:14px;padding:18px;box-shadow:0 4px 14px -8px rgba(15,23,42,.12);min-height:120px;display:flex;flex-direction:column;justify-content:center}' +
'.dn-med-fig svg{display:block;width:100%;height:auto;max-width:100%}' +
'.dn-med-fig figcaption{margin-top:10px;font-family:"Noto Sans TC",sans-serif;font-size:12.5px;color:var(--ink-2,#5e574e);line-height:1.6;text-align:center;font-style:italic}' +
'.dn-med-fig-placeholder{min-height:240px;display:flex;align-items:center;justify-content:center;color:var(--muted,#8b8378);font-size:12.5px;letter-spacing:.16em;text-transform:uppercase;font-family:Inter,sans-serif}';
document.head.appendChild(st);
}
var prose = document.getElementById('proseZh') || article.querySelector('.prose');
if (!prose) return;
var h2s = prose.querySelectorAll('h2');
var hasIO = 'IntersectionObserver' in window;
var observer = hasIO ? new IntersectionObserver(function (entries) {
entries.forEach(function (entry) {
if (!entry.isIntersecting) return;
var ph = entry.target;
var key = ph.dataset.diagramKey;
var fn = DN.medDiagrams[key];
if (typeof fn !== 'function') { observer.unobserve(ph); return; }
var wrap = document.createElement('div');
wrap.innerHTML = fn();
var fig = wrap.firstElementChild;
if (fig && ph.parentNode) ph.parentNode.replaceChild(fig, ph);
observer.unobserve(ph);
});
}, { rootMargin: '300px 0px' }) : null;
spec.forEach(function (item) {
var fn = DN.medDiagrams[item.key];
if (typeof fn !== 'function') return;
var anchor = h2s[item.after];
if (!anchor) anchor = h2s[h2s.length - 1] || prose.firstElementChild;
if (!anchor) return;
if (hasIO) {
var ph = document.createElement('figure');
ph.className = 'dn-med-fig dn-med-fig-placeholder';
ph.dataset.diagramKey = item.key;
ph.innerHTML = '<span>· loading diagram ·</span>';
anchor.parentNode.insertBefore(ph, anchor.nextSibling);
observer.observe(ph);
} else {
var wrap = document.createElement('div');
wrap.innerHTML = fn();
var fig = wrap.firstElementChild;
if (fig) anchor.parentNode.insertBefore(fig, anchor.nextSibling);
}
});
};
DN.addReadingMeta = function () {
const proseEl = document.getElementById('proseZh') || document.querySelector('article .prose');
if (!proseEl) return;
const text = (proseEl.textContent || '').replace(/\s+/g, '');
const cjkChars = (text.match(/[一-鿿]/g) || []).length;
const otherWords = (text.match(/[A-Za-z0-9]+/g) || []).length;
const minutes = Math.max(2, Math.round(cjkChars / 350 + otherWords / 200));
const slug = DN.currentSlug();
const meta = (DN.ARTICLES || []).find(function (a) { return a.slug === slug; });
const reviewedDate = meta ? meta.date : '2026-05-04';
const h1 = document.querySelector('article h1, section h1');
const lead = h1 ? h1.parentElement.querySelector('p') : null;
const target = lead || h1;
if (!target) return;
if (document.getElementById('dn-reading-meta')) return;
const bar = document.createElement('div');
bar.id = 'dn-reading-meta';
bar.style.cssText = 'display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin:14px 0 8px;font-size:12.5px;color:var(--ink-2);';
const articleNum = DN.getArticleNumber(slug);
const numBadge = articleNum
? '<span style="display:inline-flex;align-items:center;gap:5px;padding:4px 10px;border-radius:9999px;background:linear-gradient(180deg,#a4b5a8,#4d6358);color:#fff;font-weight:700;letter-spacing:.04em;font-family:Inter,sans-serif"><span aria-hidden="true">№</span><span>' + articleNum + '</span></span>'
: '';
bar.innerHTML =
numBadge +
'<span style="display:inline-flex;align-items:center;gap:5px;padding:4px 10px;border-radius:9999px;background:#f1ece4;border:1px solid #a5f3fc;color:#4d6358;font-weight:600">' +
'<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>' +
'<span data-zh="閱讀約 ' + minutes + ' 分鐘" data-en="' + minutes + ' min read">閱讀約 ' + minutes + ' 分鐘</span>' +
'</span>' +
'<span style="display:inline-flex;align-items:center;gap:5px;padding:4px 10px;border-radius:9999px;background:#dcfce7;border:1px solid #86efac;color:#14532d;font-weight:600">' +
'<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>' +
'<span data-zh="最後審閱 ' + reviewedDate + '" data-en="Last reviewed · ' + reviewedDate + '">最後審閱 ' + reviewedDate + '</span>' +
'</span>' +
'<a href="/about" style="display:inline-flex;align-items:center;gap:4px;padding:4px 10px;border-radius:9999px;background:#fff;border:1px solid var(--border);color:var(--teal-deep);text-decoration:none;font-weight:600" data-zh="陳翊嘉醫師 →" data-en="Dr. Chen Yi-Jia →">陳翊嘉醫師 →</a>';
target.parentNode.insertBefore(bar, target.nextSibling);
if (slug) {
var article = document.querySelector('article.max-w-3xl') || document.querySelector('article');
if (!article) return;
var pageOpenTime = Date.now();
var marked = false;
var THRESHOLD_PCT = 0.70;
var MIN_DWELL_MS = 30000;
function checkProgress() {
if (marked) return;
if (Date.now() - pageOpenTime < MIN_DWELL_MS) return;
var rect = article.getBoundingClientRect();
var articleTop = rect.top + window.scrollY;
var articleHeight = article.scrollHeight;
var scrolled = window.scrollY + window.innerHeight - articleTop;
var pct = scrolled / articleHeight;
if (pct >= THRESHOLD_PCT) {
marked = true;
DN.markRead(slug);
window.removeEventListener('scroll', checkProgress);
if (typeof gtag === 'function') {
try { gtag('event', 'article_read_threshold', { slug: slug }); } catch (e) {}
}
}
}
var ticking = false;
window.addEventListener('scroll', function () {
if (!ticking) {
requestAnimationFrame(function () { checkProgress(); ticking = false; });
ticking = true;
}
}, { passive: true });
var iv = setInterval(function () {
checkProgress();
if (marked) clearInterval(iv);
}, 5000);
}
};
DN.addInlineTOC = function () {
var proseEl = document.getElementById('proseZh') || document.querySelector('article .prose');
if (!proseEl) return;
if (document.getElementById('dn-inline-toc')) return;
var h2s = proseEl.querySelectorAll('h2[id]');
if (h2s.length < 3) return;
var details = document.createElement('details');
details.id = 'dn-inline-toc';
details.open = true;
details.style.cssText = 'margin:18px 0 24px;background:linear-gradient(135deg,#f5fbfa 0%,#ecfeff 100%);border:1px solid #a5f3fc;border-radius:14px;padding:0;overflow:hidden';
var summary = document.createElement('summary');
summary.style.cssText = 'cursor:pointer;list-style:none;padding:14px 18px;font-size:13px;font-weight:700;color:#0c5159;display:flex;align-items:center;justify-content:space-between;gap:8px;user-select:none';
summary.innerHTML =
'<span style="display:inline-flex;align-items:center;gap:8px">' +
'<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
'<line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/><line x1="8" y1="18" x2="21" y2="18"/>' +
'<line x1="3" y1="6" x2="3.01" y2="6"/><line x1="3" y1="12" x2="3.01" y2="12"/><line x1="3" y1="18" x2="3.01" y2="18"/>' +
'</svg>' +
'<span data-zh="本篇大綱" data-en="In this article">本篇大綱</span>' +
'<span style="font-size:11px;font-weight:600;color:#4d6358;opacity:.7">· ' + h2s.length + ' 段</span>' +
'</span>' +
'<span style="font-size:11px;color:#4d6358;opacity:.7" data-zh="點擊收合" data-en="Click to collapse">點擊收合</span>';
details.appendChild(summary);
var ol = document.createElement('ol');
ol.style.cssText = 'list-style:none;counter-reset:toc;padding:4px 18px 14px;margin:0;display:flex;flex-direction:column;gap:2px';
h2s.forEach(function (h, i) {
var li = document.createElement('li');
li.style.cssText = 'counter-increment:toc;position:relative;padding:5px 4px 5px 32px';
li.innerHTML =
'<span style="position:absolute;left:0;top:5px;width:24px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:10.5px;font-weight:700;color:#0e7c86;background:#fff;border:1px solid #a5f3fc;border-radius:6px">' + (i + 1) + '</span>' +
'<a href="#' + h.id + '" data-toc-inline="' + h.id + '" style="display:block;color:var(--ink-2);text-decoration:none;font-size:13.5px;line-height:1.6;font-weight:500">' + (h.textContent || ('Section ' + (i + 1))) + '</a>';
ol.appendChild(li);
});
details.appendChild(ol);
var articleEl = document.querySelector('article');
if (articleEl && articleEl.firstElementChild) {
var h1 = articleEl.querySelector('h1');
if (h1 && h1.parentNode) {
h1.parentNode.insertBefore(details, h1.nextSibling);
} else {
articleEl.insertBefore(details, articleEl.firstElementChild);
}
} else {
proseEl.parentNode.insertBefore(details, proseEl);
}
ol.addEventListener('click', function (e) {
var a = e.target.closest('a[data-toc-inline]');
if (!a) return;
e.preventDefault();
var id = a.dataset.tocInline;
var target = document.getElementById(id);
if (target) {
var top = target.getBoundingClientRect().top + window.pageYOffset - 80;
window.scrollTo({ top: top, behavior: 'smooth' });
history.pushState(null, '', '#' + id);
if (window.gtag) window.gtag('event', 'toc_click', { section_id: id });
}
});
};
DN.bindScrollMemory = function () {
var slug = DN.currentSlug();
if (!slug) return;
var proseEl = document.getElementById('proseZh') || document.querySelector('article .prose');
if (!proseEl) return;
var KEY = 'dn:scroll:' + slug;
var MAX_AGE_MS = 14 * 24 * 60 * 60 * 1000;
function saveNow() {
try {
var docH = document.documentElement.scrollHeight - window.innerHeight;
if (docH < 100) return;
var y = window.pageYOffset;
var pct = Math.min(100, Math.max(0, Math.round((y / docH) * 100)));
if (pct < 3 || pct > 97) {
localStorage.removeItem(KEY);
return;
}
var h2s = proseEl.querySelectorAll('h2[id]');
var nearest = null;
var nearestIdx = 0;
for (var i = 0; i < h2s.length; i++) {
var top = h2s[i].getBoundingClientRect().top + window.pageYOffset;
if (top <= y + 120) { nearest = h2s[i]; nearestIdx = i; }
else break;
}
var data = {
y: y,
pct: pct,
ts: Date.now(),
h2: nearest ? (nearest.textContent || '').slice(0, 40) : '',
h2i: nearestIdx
};
localStorage.setItem(KEY, JSON.stringify(data));
} catch (e) {  }
}
var saveTimer = null;
window.addEventListener('scroll', function () {
if (saveTimer) clearTimeout(saveTimer);
saveTimer = setTimeout(saveNow, 500);
}, { passive: true });
window.addEventListener('beforeunload', saveNow);
document.addEventListener('visibilitychange', function () {
if (document.visibilityState === 'hidden') saveNow();
});
function maybePrompt() {
if (window.location.hash) return;
var raw;
try { raw = localStorage.getItem(KEY); } catch (e) { return; }
if (!raw) return;
var data;
try { data = JSON.parse(raw); } catch (e) { localStorage.removeItem(KEY); return; }
if (!data || !data.y || !data.pct) return;
if (Date.now() - (data.ts || 0) > MAX_AGE_MS) { localStorage.removeItem(KEY); return; }
if (data.pct < 5 || data.pct > 95) return;
var toast = document.createElement('div');
toast.id = 'dn-resume-toast';
toast.style.cssText =
'position:fixed;left:50%;bottom:24px;transform:translateX(-50%);z-index:9999;' +
'background:#fff;border:1px solid #a5f3fc;border-radius:14px;' +
'box-shadow:0 18px 40px -16px rgba(12,81,89,.35),0 4px 10px rgba(15,23,42,.08);' +
'padding:14px 18px;display:flex;align-items:center;gap:14px;flex-wrap:wrap;' +
'max-width:calc(100vw - 32px);font-size:13.5px;color:var(--ink);' +
'animation:dn-toast-in .35s cubic-bezier(.2,.7,.3,1)';
var label = data.h2 ? '「' + data.h2 + '」' : '';
toast.innerHTML =
'<div style="display:flex;align-items:center;gap:10px;flex:1;min-width:200px">' +
'<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#0e7c86" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
'<path d="M21 12a9 9 0 1 1-9-9c2.5 0 4.8 1 6.5 2.6L21 8"/><path d="M21 3v5h-5"/>' +
'</svg>' +
'<div style="line-height:1.5">' +
'<div style="font-weight:700;color:#0c5159">上次讀到 ' + data.pct + '%</div>' +
(label ? '<div style="font-size:12px;color:var(--ink-2);margin-top:2px">' + label + '</div>' : '') +
'</div>' +
'</div>' +
'<div style="display:flex;gap:8px;flex-shrink:0">' +
'<button type="button" data-resume-yes style="padding:7px 14px;border-radius:9999px;background:#0e7c86;color:#fff;border:0;font-weight:700;font-size:12.5px;cursor:pointer">繼續閱讀</button>' +
'<button type="button" data-resume-no style="padding:7px 12px;border-radius:9999px;background:#fff;color:var(--ink-2);border:1px solid var(--border);font-weight:600;font-size:12.5px;cursor:pointer">從頭開始</button>' +
'</div>';
if (!document.getElementById('dn-resume-style')) {
var st = document.createElement('style');
st.id = 'dn-resume-style';
st.textContent = '@keyframes dn-toast-in{from{opacity:0;transform:translate(-50%,16px)}to{opacity:1;transform:translate(-50%,0)}}';
document.head.appendChild(st);
}
document.body.appendChild(toast);
function dismiss() { if (toast.parentNode) toast.parentNode.removeChild(toast); }
toast.querySelector('[data-resume-yes]').addEventListener('click', function () {
window.scrollTo({ top: data.y, behavior: 'smooth' });
dismiss();
if (window.gtag) window.gtag('event', 'resume_reading', { slug: slug, pct: data.pct });
});
toast.querySelector('[data-resume-no]').addEventListener('click', function () {
try { localStorage.removeItem(KEY); } catch (e) {}
dismiss();
});
setTimeout(function () { if (toast.parentNode) toast.style.opacity = '0', setTimeout(dismiss, 350); }, 12000);
}
setTimeout(maybePrompt, 600);
};
DN.addFloatingTOC = function () {
const TOC_MIN_WIDTH = 1180;
if (window.innerWidth < TOC_MIN_WIDTH) return;
const proseEl = document.getElementById('proseZh')
|| document.querySelector('article.prose')
|| document.querySelector('article .prose')
|| document.querySelector('article.max-w-3xl');
if (!proseEl) return;
var allH2 = proseEl.querySelectorAll('h2');
allH2.forEach(function (h, i) {
if (!h.id) {
var slug = (h.textContent || '').toLowerCase()
.replace(/[^\w一-鿿]+/g, '-')
.replace(/^-+|-+$/g, '')
.slice(0, 40) || ('h2-' + i);
h.id = slug;
}
});
const h2s = proseEl.querySelectorAll('h2[id]');
if (h2s.length < 3) return;
if (document.getElementById('dn-toc-float')) return;
const aside = document.createElement('aside');
aside.id = 'dn-toc-float';
aside.style.cssText = [
'position:fixed',
'left:max(8px, calc(50% - 384px - clamp(160px, 14vw, 220px) - 30px))',
'top:clamp(96px, 12vh, 140px)',
'width:clamp(150px, 14vw, 210px)',
'max-height:calc(100vh - 160px)',
'overflow-y:auto',
'padding:clamp(10px, 1vw, 14px) clamp(11px, 1.1vw, 16px)',
'background:rgba(255,255,255,.92)',
'backdrop-filter:blur(8px)',
'-webkit-backdrop-filter:blur(8px)',
'border:1px solid var(--border)',
'border-radius:12px',
'box-shadow:0 12px 28px -14px rgba(77,99,88,.22)',
'font-size:clamp(11px, 0.95vw, 12.5px)',
'line-height:1.6',
'z-index:30'
].join(';');
let html = '<div style="font-size:clamp(9.5px, 0.78vw, 10.5px);text-transform:uppercase;letter-spacing:.18em;color:var(--teal-deep);font-weight:700;margin-bottom:8px" data-zh="本篇大綱" data-en="In this article">本篇大綱</div><ul style="list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:3px" id="dn-toc-list">';
h2s.forEach(function (h, i) {
const maxChars = window.innerWidth >= 1400 ? 26 : (window.innerWidth >= 1280 ? 22 : 18);
const txt = (h.textContent || ('Section ' + (i + 1))).trim();
const shown = txt.length > maxChars ? txt.slice(0, maxChars - 1) + '…' : txt;
html += '<li><a href="#' + h.id + '" data-toc="' + h.id + '" title="' + txt.replace(/"/g, '&quot;') + '" style="display:block;padding:4px 8px;border-radius:6px;color:var(--ink-2);text-decoration:none;border-left:2px solid transparent;transition:all .15s;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">' + shown + '</a></li>';
});
html += '</ul>';
aside.innerHTML = html;
document.body.appendChild(aside);
const links = aside.querySelectorAll('a[data-toc]');
function setActive(id) {
links.forEach(function (l) {
const active = l.dataset.toc === id;
l.style.color = active ? 'var(--teal-deep)' : 'var(--ink-2)';
l.style.background = active ? 'var(--mint-soft)' : 'transparent';
l.style.borderLeftColor = active ? 'var(--teal)' : 'transparent';
l.style.fontWeight = active ? '700' : '500';
});
}
const io = new IntersectionObserver(function (entries) {
const visible = entries.filter(function (e) { return e.isIntersecting; });
if (visible.length) setActive(visible[0].target.id);
}, { rootMargin: '-30% 0px -50% 0px' });
h2s.forEach(function (h) { io.observe(h); });
aside.style.transition = 'opacity .25s, visibility .25s';
aside.style.willChange = 'opacity';
var hideAnchor = document.querySelector('#dn-author-bio, #dn-legal-disclaimer, footer.mag-footer, footer');
if (!hideAnchor) {
var attachObs = new MutationObserver(function () {
var el = document.querySelector('#dn-author-bio, #dn-legal-disclaimer, footer.mag-footer, footer');
if (el) {
attachObs.disconnect();
attachHide(el);
}
});
attachObs.observe(document.body, { childList: true, subtree: true });
} else {
attachHide(hideAnchor);
}
function attachHide(target) {
var io2 = new IntersectionObserver(function (entries) {
entries.forEach(function (e) {
if (e.isIntersecting) {
aside.style.opacity = '0';
aside.style.visibility = 'hidden';
aside.style.pointerEvents = 'none';
} else {
aside.style.opacity = '';
aside.style.visibility = '';
aside.style.pointerEvents = '';
}
});
}, { rootMargin: '0px 0px -40% 0px' });
io2.observe(target);
}
let lastWidth = window.innerWidth;
window.addEventListener('resize', function () {
const w = window.innerWidth;
aside.style.display = (w >= TOC_MIN_WIDTH) ? '' : 'none';
const crossedBreak =
(lastWidth < 1280 && w >= 1280) ||
(lastWidth >= 1280 && w < 1280) ||
(lastWidth < 1400 && w >= 1400) ||
(lastWidth >= 1400 && w < 1400);
if (crossedBreak) {
aside.querySelectorAll('a[data-toc]').forEach(function (a) {
const id = a.dataset.toc;
const h = document.getElementById(id);
if (!h) return;
const txt = (h.textContent || '').trim();
const maxChars = w >= 1400 ? 26 : (w >= 1280 ? 22 : 18);
a.textContent = txt.length > maxChars ? txt.slice(0, maxChars - 1) + '…' : txt;
});
}
lastWidth = w;
});
};
DN.addFontSizer = function () {
if (document.getElementById('dn-font-sizer')) return;
if (location.pathname.startsWith('/admin')) return;
if (!document.querySelector('.prose, #proseZh, .prose-zh')) return;
var savedSize = localStorage.getItem('dn-font-size') || 'M';
var sizeMap = { 'S': '15px', 'M': '16.5px', 'L': '18.5px', 'XL': '21px' };
var lineHeightMap = { 'S': '1.7', 'M': '1.85', 'L': '1.95', 'XL': '2.05' };
function applyFontSize(s) {
var styleEl = document.getElementById('dn-font-size-style');
if (!styleEl) {
styleEl = document.createElement('style');
styleEl.id = 'dn-font-size-style';
document.head.appendChild(styleEl);
}
var px = sizeMap[s] || sizeMap.M;
var lh = lineHeightMap[s] || lineHeightMap.M;
styleEl.textContent =
'.prose, .prose-zh, .prose-en, #proseZh, #proseEn, article.prose { font-size: ' + px + ' !important; line-height: ' + lh + ' !important; }' +
'.prose p, .prose-zh p, .prose-en p, #proseZh p, #proseEn p, article.prose p, article.prose li { font-size: ' + px + ' !important; line-height: ' + lh + ' !important; }' +
(s === 'XL'
? 'article h2 { font-size: 1.55em !important; } article h3 { font-size: 1.28em !important; } article h4 { font-size: 1.12em !important; }'
: '');
localStorage.setItem('dn-font-size', s);
}
applyFontSize(savedSize);
var wrap = document.createElement('div');
wrap.id = 'dn-font-sizer';
wrap.setAttribute('aria-label', '字型大小調整');
var isMobile = (typeof window !== 'undefined') && window.matchMedia && window.matchMedia('(max-width: 767px)').matches;
var fsBottom = isMobile ? '88px' : '24px';
wrap.style.cssText =
'position:fixed;right:18px;bottom:' + fsBottom + ';z-index:49;display:flex;flex-direction:column;' +
'background:#fff;border:1px solid var(--border, #dcd5c8);border-radius:22px;' +
'box-shadow:0 6px 18px -8px rgba(77,99,88,.45);overflow:hidden;opacity:0;' +
'pointer-events:none;transition:opacity .25s;';
['S', 'M', 'L', 'XL'].forEach(function (s) {
var b = document.createElement('button');
b.type = 'button';
b.dataset.size = s;
b.style.cssText =
'width:38px;height:32px;border:0;cursor:pointer;font-weight:700;color:#4d6358;' +
'background:' + (s === savedSize ? 'linear-gradient(180deg,#a4b5a8,#4d6358)' : 'transparent') + ';' +
'color:' + (s === savedSize ? '#fff' : '#4d6358') + ';';
var labels = { 'S': { px: '11px', txt: '小' }, 'M': { px: '13px', txt: '中' }, 'L': { px: '15px', txt: '大' }, 'XL': { px: '17px', txt: '特大' } };
b.style.fontSize = labels[s].px;
b.textContent = labels[s].txt;
b.setAttribute('aria-label', '字型大小 ' + s);
b.title = '字型大小 ' + labels[s].txt + (s === 'XL' ? '(高齡友善)' : '');
b.addEventListener('click', function () {
applyFontSize(s);
wrap.querySelectorAll('button').forEach(function (x) {
x.style.background = 'transparent';
x.style.color = '#4d6358';
});
b.style.background = 'linear-gradient(180deg,#a4b5a8,#4d6358)';
b.style.color = '#fff';
if (typeof gtag === 'function') {
try { gtag('event', 'font_size_change', { size: s, page_path: location.pathname }); } catch (e) {}
}
});
wrap.appendChild(b);
});
document.body.appendChild(wrap);
var ticking = false;
function update() {
var scrolled = window.scrollY > 400;
wrap.style.opacity = scrolled ? '1' : '0';
wrap.style.pointerEvents = scrolled ? 'auto' : 'none';
ticking = false;
}
window.addEventListener('scroll', function () {
if (!ticking) { requestAnimationFrame(update); ticking = true; }
}, { passive: true });
update();
};
})();
